SELECT COUNT(*) AS Total_Repositories
FROM github_repositories;

SELECT *
FROM github_repositories
LIMIT 10;
 
 
SELECT 
    Company,
    COUNT(*) AS Repository_Count
FROM github_repositories
GROUP BY Company
ORDER BY Repository_Count DESC;

SELECT
    Company,
    COUNT(*) AS Repository_Count,
    SUM(Stars) AS Total_Stars,
    SUM(Forks) AS Total_Forks,
    SUM(Watchers) AS Total_Watchers,
    SUM(Open_Issues) AS Total_Open_Issues
FROM github_repositories
GROUP BY Company
ORDER BY Total_Stars DESC;

SELECT
    Programming_Language,
    COUNT(*) AS Repository_Count
FROM github_repositories
WHERE Programming_Language IS NOT NULL
GROUP BY Programming_Language
ORDER BY Repository_Count DESC;

SELECT
    Company,
    Archived,
    COUNT(*) AS Repository_Count
FROM github_repositories
GROUP BY Company, Archived
ORDER BY Company, Archived;

SELECT
    YEAR(Created_Date) AS Creation_Year,
    COUNT(*) AS Repository_Count
FROM github_repositories
GROUP BY YEAR(Created_Date)
ORDER BY Creation_Year;

CREATE VIEW company_performance_summary AS
SELECT
    Company,
    COUNT(*) AS Repository_Count,
    SUM(Stars) AS Total_Stars,
    SUM(Forks) AS Total_Forks,
    SUM(Watchers) AS Total_Watchers,
    SUM(Open_Issues) AS Total_Open_Issues
FROM github_repositories

GROUP BY Company;


SELECT *
FROM company_performance_summary;

